import{_ as a,C as c,o as t,c as s,ah as o,E as r}from"./chunks/framework.C2WMkNym.js";const m=JSON.parse('{"title":"다른 유틸리티 라이브러리와의 비교","description":"Lodash, Underscore.js, quiver, basic_utils, pydash, boltons와 qsu를 영역별로 비교합니다.","frontmatter":{"order":1,"menuTitle":"비교","description":"Lodash, Underscore.js, quiver, basic_utils, pydash, boltons와 qsu를 영역별로 비교합니다."},"headers":[],"relativePath":"ko/discover-more/comparison.md","filePath":"ko/discover-more/comparison.md","lastUpdated":1789967602000}'),i={name:"ko/discover-more/comparison.md"};function l(n,e,p,h,u,q){const d=c("FeatureMatrix");return t(),s("div",null,[e[0]||(e[0]=o('<h1 id="다른-유틸리티-라이브러리와의-비교" tabindex="-1">다른 유틸리티 라이브러리와의 비교 <a class="header-anchor" href="#다른-유틸리티-라이브러리와의-비교" aria-label="Permalink to &quot;다른 유틸리티 라이브러리와의 비교&quot;">​</a></h1><p>qsu는 세 언어 어디에서도 최초의 유틸리티 라이브러리가 아니고, 대부분의 프로젝트에서 유일한 라이브러리도 아닐 것입니다. 이 문서는 qsu가 무엇을 다루는지, 더 알려진 대안은 무엇을 다루는지, 어떤 일에 어느 쪽이 맞는지를 정리합니다.</p><p>사이드바에서 언어를 고르면 그 언어 기준으로 내용이 바뀝니다. 각 라이브러리에는 <a href="/ko/discover-more/">마이그레이션 문서</a>도 따로 있습니다.</p><h2 id="비교-대상" tabindex="-1">비교 대상 <a class="header-anchor" href="#비교-대상" aria-label="Permalink to &quot;비교 대상&quot;">​</a></h2><div class="lang-only" data-code-lang="js"><p>**<a href="https://lodash.com" target="_blank" rel="noreferrer">Lodash</a>**는 거의 모든 JavaScript 프로젝트가 한 번쯤 써 본 라이브러리입니다. 배열·객체·문자열을 중심으로 한 크고 안정적인 모음이며, 그 위에 커링, 체이닝, iteratee 축약 표기, <code>fp</code> 빌드 같은 함수형 계층이 얹혀 있습니다.</p><p>**<a href="https://underscorejs.org" target="_blank" rel="noreferrer">Underscore.js</a>**가 먼저 나왔고 규모는 더 작습니다. Lodash가 Underscore를 포크해 시작했기 때문에 이름 대부분이 겹치며, Underscore는 이후 범위를 넓히지 않고 좁게 유지해 왔습니다.</p></div><div class="lang-only" data-code-lang="dart"><p>**<a href="https://pub.dev/packages/quiver" target="_blank" rel="noreferrer">quiver</a>**는 Google이 Apache-2.0으로 배포합니다. 유틸리티 모음이라기보다 SDK를 보완하는 쪽에 가깝습니다. Python의 <code>itertools</code>를 닮은 이터러블, SDK에 없는 <code>BiMap</code>·<code>Multimap</code> 같은 컬렉션 타입, 캐시, 인자 검사, 주입 가능한 <code>Clock</code>을 제공합니다.</p><p>**<a href="https://pub.dev/packages/basic_utils" target="_blank" rel="noreferrer">basic_utils</a>**는 정적 메서드를 담은 <code>*Utils</code> 클래스의 모음입니다. <code>StringUtils</code>, <code>MathUtils</code>, <code>IterableUtils</code>, <code>EmailUtils</code>, <code>DomainUtils</code>, <code>HttpUtils</code>, <code>DnsUtils</code>가 있고, <code>X509Utils</code>·<code>PKCS12Utils</code>·<code>ASN1Utils</code>로 이루어진 인증서·암호 영역이 큰 비중을 차지합니다.</p></div><div class="lang-only" data-code-lang="python"><p>**<a href="https://pydash.readthedocs.io" target="_blank" rel="noreferrer">pydash</a>**는 Lodash의 이식판입니다. 이름은 Lodash를 <code>snake_case</code>로 옮긴 것이고 인자도 Lodash를 따르며, 체이닝과 콜백 축약 표기까지 그대로 가져왔습니다.</p><p>**<a href="https://boltons.readthedocs.io" target="_blank" rel="noreferrer">boltons</a>**는 &quot;표준 라이브러리와 같은 결&quot;을 지향하는 순수 Python 모듈 모음입니다. <code>strutils</code>, <code>iterutils</code>, <code>fileutils</code>, <code>timeutils</code>, <code>cacheutils</code> 등 스무 개가 넘습니다. 표준 라이브러리에 있었어야 했는데 없는 부분을 채우는 성격이라 이름도 <code>stdlib</code> 관례를 따릅니다.</p></div><h2 id="기능-시트" tabindex="-1">기능 시트 <a class="header-anchor" href="#기능-시트" aria-label="Permalink to &quot;기능 시트&quot;">​</a></h2><p>각 행은 질문 하나이고, qsu와 그 옆의 두 라이브러리에 같은 질문을 던집니다. 시트는 언어 스위치를 따르므로 열은 지금 고른 생태계의 것이고, 한 생태계에서만 의미가 있는 질문(Dart의 인증서, Python의 원자적 쓰기)은 그 시트에만 나옵니다.</p><p>표시는 결론이 아니라 출발점입니다. 두 함수가 모두 체크를 받아도 인자나 기본값, 경계 동작은 다를 수 있습니다. 그 차이를 다루는 것이 마이그레이션 문서입니다.</p>',10)),r(d),e[1]||(e[1]=o('<h2 id="qsu가-하지-않는-일" tabindex="-1">qsu가 하지 않는 일 <a class="header-anchor" href="#qsu가-하지-않는-일" aria-label="Permalink to &quot;qsu가 하지 않는 일&quot;">​</a></h2><p>위 표는 qsu를 기준으로 그린 것이니, 반대 방향도 적어 둡니다.</p><p>qsu에는 체이닝도, 커링도, 콜백 축약 표기도 없습니다. 모든 함수는 따로 호출하고 실제 인자를 받습니다. 그래서 <code>_.chain</code>도, <code>fp</code> 빌드도, 문자열이나 객체로 쓰는 iteratee도 없습니다.</p><p>고차 함수 도구도 없습니다. <code>memoize</code>, <code>once</code>, <code>curry</code>, <code>partial</code>, 함수 합성에 해당하는 것이 하나도 없습니다. <code>debounce</code>와 <code>throttle</code>, <code>retry</code>가 있는 이유는 타이밍 문제를 풀기 때문이지, qsu가 함수를 감싸는 일을 하기 때문이 아닙니다.</p><p>언어가 이미 잘하는 일은 언어에 맡깁니다. 매핑, 필터링, 리듀스, 정렬, 자르기, 묶기, 이어 붙이기는 요즘 JavaScript와 Dart, Python에서 모두 한 번의 호출이므로 qsu는 다시 만들지 않습니다.</p><div class="lang-only" data-code-lang="js"><p>Lodash에는 qsu에 어떤 수준으로도 대응되지 않는 기능이 더 있습니다. <code>_.template</code>, 정렬된 배열의 삽입 위치를 찾는 함수들, <code>_.zip</code>과 <code>_.unzip</code>, 키와 방향을 여러 개 받는 <code>_.orderBy</code>, 그리고 원본을 바꾸는 <code>_.pull</code>·<code>_.remove</code>·<code>_.fill</code>입니다.</p></div><div class="lang-only" data-code-lang="dart"><p>quiver의 컬렉션 타입에는 대응되는 것이 없습니다. <code>BiMap</code>, <code>Multimap</code>, <code>LruMap</code>, <code>TreeSet</code>이 필요하다면 그것이 quiver를 쓰는 이유이고, qsu가 대신할 수 있는 것은 없습니다. 시간에 의존하는 코드를 테스트하기 위한 주입 가능한 <code>Clock</code>도 마찬가지입니다.</p><p>basic_utils는 인증서 쪽으로 qsu보다 훨씬 멀리 갑니다. qsu는 해시하고 인코딩하고 암호화하지만, X.509나 PKCS12, ASN.1을 읽거나 쓰지는 않습니다.</p></div><div class="lang-only" data-code-lang="python"><p>pydash에는 qsu가 빼 둔 함수형 계층이 통째로 있고, 컬렉션 API의 상당 부분은 <code>map</code>·<code>filter</code>·<code>itertools</code>가 이미 해 주는 일로 돌아옵니다. boltons는 <code>remap</code>과 <code>research</code>로 중첩 자료구조를, <code>atomic_save</code>로 원자적 파일 쓰기를, <code>OrderedMultiDict</code>와 <code>IndexedSet</code>으로 자료구조를 qsu보다 깊게 다룹니다.</p></div><h2 id="api의-모양" tabindex="-1">API의 모양 <a class="header-anchor" href="#api의-모양" aria-label="Permalink to &quot;API의 모양&quot;">​</a></h2><p>qsu의 모든 함수는 <code>camelCase</code> 이름을 가진 평범한 함수입니다. 선택 인자는 마지막에 하나로 모여서, JavaScript에서는 객체, Dart에서는 named 파라미터, Python에서는 키워드 인자나 <code>dict</code> 하나로 전달됩니다. 같은 동작에 이름을 여러 개 두지 않습니다. <a href="/ko/reference/string/pad">pad</a>는 함수 세 개로 나뉘는 대신 <code>position</code> 옵션을 받고, <a href="/ko/reference/object/objClone">objClone</a>은 두 개로 나뉘는 대신 <code>deep</code>을 받습니다.</p><div class="lang-only" data-code-lang="js"><p>Lodash와 Underscore도 데이터를 먼저 받고 새 값을 돌려주므로, 호출의 모양 자체는 qsu와 같습니다. 다른 것은 그 위의 계층입니다. Lodash는 콜백 자리에 속성 이름이나 객체, 배열을 받고, <code>_.get</code>과 <code>_.set</code>은 문자열로 쓴 경로를 읽습니다. qsu는 콜백을 콜백으로만 받고, 경로를 읽는 것은 <a href="/ko/reference/object/objGet">objGet</a>뿐입니다.</p></div><div class="lang-only" data-code-lang="dart"><p>quiver와 basic_utils는 서로 모양이 다릅니다. quiver는 최상위 함수를 내보내므로 <code>isBlank(s)</code>는 qsu의 <code>trim(s)</code>과 같은 방식으로 읽힙니다. basic_utils는 모두 정적 메서드를 가진 클래스로 묶어서 같은 호출이 <code>StringUtils.isNullOrEmpty(s)</code>가 됩니다. qsu는 여기서 quiver 쪽입니다. 함수는 최상위에 있고 한 곳에서 가져옵니다.</p><p>이름은 일부러 Dart답지 않게 지었습니다. <code>toCamelCase</code>나 확장 메서드가 아니라 <code>strToCamelCase</code>인 이유는, Dart 패키지가 JavaScript·Python 패키지와 똑같이 읽혀야 하기 때문입니다.</p></div><div class="lang-only" data-code-lang="python"><p>pydash는 내장 함수와 충돌하는 이름 뒤에 밑줄을 붙여서 <code>pydash.map_</code>, <code>pydash.filter_</code>, <code>pydash.sum_</code>으로 씁니다. boltons는 표준 라이브러리를 따라 그룹마다 모듈을 두므로 <code>from boltons.strutils import slugify</code>처럼 가져옵니다.</p><p>qsu는 둘 다 하지 않습니다. Python에서도 이름은 <code>camelCase</code>이고 패키지 루트에서 가져옵니다. Python다운 방식은 아니며, 세 언어의 API를 같게 유지하기 위해 치르는 값입니다.</p></div><h2 id="어디에서-돌아가는가" tabindex="-1">어디에서 돌아가는가 <a class="header-anchor" href="#어디에서-돌아가는가" aria-label="Permalink to &quot;어디에서 돌아가는가&quot;">​</a></h2><div class="lang-only" data-code-lang="js"><p>qsu는 ESM 전용이고 Node 20 이상이 필요합니다. 의존성이 없고 사이드 이펙트가 없다고 표시되어 있으며, 카테고리마다 서브패스가 있어서 <code>import { trim } from &#39;qsu/string&#39;</code>은 그 카테고리만 가져옵니다. Node 런타임이 필요한 함수는 <code>qsu/node</code> 뒤에 있어서 브라우저용 절반은 브라우저용으로 남습니다. TypeScript 타입은 패키지에 함께 들어 있습니다.</p><p>Lodash가 배포하는 진입점은 <code>exports</code> 맵이 없는 CommonJS 파일 하나입니다. ESM 빌드는 <code>lodash-es</code>라는 별도 패키지이고, 번들에서 트리셰이킹이 되는지는 그 패키지를 쓰는지에 달려 있습니다. Underscore는 조건부 exports로 두 빌드를 한 패키지에서 내보냅니다. 둘 다 타입 선언을 직접 배포하지 않아 DefinitelyTyped에서 가져옵니다.</p></div><div class="lang-only" data-code-lang="dart"><p>qsu는 Dart 3.5 이상이 필요하고 <code>path</code>, <code>crypto</code>, <code>unorm_dart</code>, <code>ffi</code>, <code>pointycastle</code>에 의존합니다. <code>os</code> 카테고리는 macOS와 Windows에서 <code>dart:ffi</code>로, Linux와 Android에서 <code>/proc</code>으로 운영 체제에 접근하므로 웹에서는 <code>UnsupportedError</code>를 던집니다. 나머지는 웹에서도 그대로 동작합니다.</p><p>quiver는 순수 Dart이고 의존성이 하나입니다. basic_utils도 순수 Dart이지만 HTTP 클라이언트와 암호 구현을 포함해 여러 의존성을 함께 가져옵니다. 인증서 쪽 기능이 그 위에 올라가 있습니다.</p></div><div class="lang-only" data-code-lang="python"><p>qsu는 Python 3.8 이상이 필요하고 <code>cryptography</code>에 의존합니다. <code>crypto</code> 카테고리가 그 위에 올라가 있습니다.</p><p>pydash는 순수 Python이지만 3.10 이상을 요구하므로, 낮은 인터프리터에 묶여 있다면 먼저 확인해야 할 부분입니다. boltons는 의존성이 전혀 없는 순수 Python이고 지원 범위도 둘 중 가장 넓습니다.</p></div><h2 id="qsu에만-있는-것" tabindex="-1">qsu에만 있는 것 <a class="header-anchor" href="#qsu에만-있는-것" aria-label="Permalink to &quot;qsu에만 있는 것&quot;">​</a></h2><p>같은 이름의 같은 함수가 JavaScript와 Dart, Python에서 같은 결과를 냅니다. API는 Node로, 앱은 Flutter로, 데이터 작업은 Python으로 쓰는 서비스라면 제목을 슬러그로 바꾸고 파일 용량을 표시하고 이메일을 검증하고 값을 해시하는 일을 세 곳에서 같은 방식으로 할 수 있습니다. 언어를 오가는 개발자도 쓰던 도구를 그대로 씁니다.</p><p>이 문서의 어떤 라이브러리도 그것을 시도하지 않습니다. 시도할 자리가 없기 때문입니다. Lodash는 JavaScript이고 quiver는 Dart이며 boltons는 Python입니다. pydash가 Lodash의 이름을 옮겨 와서 가장 가깝지만, 이식은 닮음이지 보증이 아닙니다. 두 프로젝트는 따로 관리되고 서로의 동작에 책임지지 않습니다.</p><p>qsu에서 이 일관성은 구호가 아니라 테스트로 지킵니다. 테스트는 구현과 함께 이식되고, 한 패키지에만 있는 몇 안 되는 함수는 조용히 빠지는 대신 <a href="/ko/reference/">문서에 표시</a>됩니다.</p><h2 id="무엇을-쓸-것인가" tabindex="-1">무엇을 쓸 것인가 <a class="header-anchor" href="#무엇을-쓸-것인가" aria-label="Permalink to &quot;무엇을 쓸 것인가&quot;">​</a></h2><p>Lodash, quiver, basic_utils, pydash, boltons는 각자 잘하는 일에 그대로 쓰면 됩니다. qsu와 충돌하지 않으며, qsu를 넣기 위해 무언가를 뺄 이유도 없습니다.</p><p>qsu는 여러 언어에서 하나의 API를 쓰고 싶을 때, qsu가 다루고 다른 라이브러리는 다루지 않는 것(파일 용량, 시간, 슬러그, 해시, 시스템 정보, 파일 처리)이 필요할 때, 또는 같은 헬퍼를 네 번째로 직접 쓰게 될 때 꺼내면 됩니다.</p><p>반대로 qsu에 없는 함수형 계층에 기대고 있거나, qsu가 제공하지 않는 컬렉션 타입 위에 코드가 올라가 있거나, 쓰는 헬퍼가 이미 언어의 표준 라이브러리에 있다면 지금 쓰는 것을 그대로 두세요.</p>',25))])}const y=a(i,[["render",l]]);export{m as __pageData,y as default};
